import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl-lang repo structure","description":"","frontmatter":{},"headers":[],"relativePath":"structure.md","filePath":"structure.md"}`),a={name:`structure.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-lang-repo-structure" tabindex="-1">handl-lang repo structure <a class="header-anchor" href="#handl-lang-repo-structure" aria-label="Permalink to “handl-lang repo structure”">​</a></h1><p>~110 private repos under <code>github.com/handl-lang</code>, checked out as siblings in <code>~/GitHub/handl-lang/</code>. Deps are git deps (<code>branch = &quot;main&quot;</code>); workspace-root <code>[patch]</code> tables resolve them from sibling checkouts (ADR-0128).</p><h2 id="core-layers-bare" tabindex="-1">Core layers (bare) <a class="header-anchor" href="#core-layers-bare" aria-label="Permalink to “Core layers (bare)”">​</a></h2><ul><li><code>host</code> — runtime, loaders, <code>plugin-lib-*</code>/<code>plugin-ext-*</code> internals, <code>plugin-lib-stdlib</code> (the library-as-data registry)</li><li><code>kernel</code> — <code>handl-language</code>, <code>handl-value</code>, <code>handl-ext</code>, plus substrate ops: <code>prim</code>, <code>prim-handl</code>, <code>ops</code>, <code>bytes</code>, <code>cmp</code>, <code>error</code>, <code>obj</code>, <code>type</code>, <code>mood</code>, <code>combinators</code></li><li><code>kit-data-canonical</code> — <code>handl-kit-data-canonical</code> + <code>data/*.yaml</code> (the canonical language definition, language-as-data)</li><li><code>meta</code> — <code>defining-handl</code> (self-hosting, ADR-0044 Phase 8)</li><li><code>docs</code> <code>project</code> <code>automation</code> <code>bench</code> <code>playground</code> <code>assets</code></li></ul><h2 id="engine-17" tabindex="-1"><code>engine-*</code> (17) <a class="header-anchor" href="#engine-17" aria-label="Permalink to “engine-* (17)”">​</a></h2><p><code>engine</code> · <code>engine-{lex,lex-pattern,parse,parse-pratt,exec,exec-tree-walk,exec-bytecode,exec-cranelift,fmt,lint,test,transform,transform-rewrite,typecheck,typecheck-nbe}</code></p><h2 id="compile-5" tabindex="-1"><code>compile-*</code> (5) <a class="header-anchor" href="#compile-5" aria-label="Permalink to “compile-* (5)”">​</a></h2><p><code>compile-{dot,sexp,term,handl,js}</code></p><h2 id="sdkgen-5" tabindex="-1"><code>sdkgen-*</code> (5) <a class="header-anchor" href="#sdkgen-5" aria-label="Permalink to “sdkgen-* (5)”">​</a></h2><p><code>sdkgen-{c,python,webidl,file,cli}</code> — backends/emitters; generated FFI bindings vendor under <code>handl-packages/generated/</code> in the consuming repo (multi-consumer bindings get own repos: <code>lib-libc</code>, <code>lib-curl</code>, <code>lib-libz</code>). <code>sdkgen-cli</code> generates SDKs that wrap command-line tools (backend <code>cli</code>: <code>*.clispec.yaml</code> spec or live <code>--help</code> probe; emitter <code>hnl-cli</code> → adapters on <code>lib-cli</code>&#39;s <code>cli-c</code> process-spawn runtime); generated CLI SDKs are committed as spec+gate repos with <code>generated/</code> gitignored (<code>lib-gh</code>, <code>lib-cli-gen</code> for multi-tool SDKs).</p><h2 id="host-3" tabindex="-1"><code>host-*</code> (3) <a class="header-anchor" href="#host-3" aria-label="Permalink to “host-* (3)”">​</a></h2><p><code>host-{cli,lsp,tensor}</code></p><h2 id="ext-10" tabindex="-1"><code>ext-*</code> (10) <a class="header-anchor" href="#ext-10" aria-label="Permalink to “ext-* (10)”">​</a></h2><p><code>ext-{compile,eval,fmt,kit,lint,plugin,sdkgen,test,transform,typecheck}</code> — <code>hnl</code> extensions (<code>libhnl_ext_*.so</code> discovered via <code>HANDL_EXT_DIR</code>/<code>~/.handl/ext</code>).</p><h2 id="lib-80" tabindex="-1"><code>lib-*</code> (~80) <a class="header-anchor" href="#lib-80" aria-label="Permalink to “lib-* (~80)”">​</a></h2><p><strong>Rule: one package per repo — <code>.hnl</code> codebases only, no Rust</strong> (crates are const-only <code>*_HNL</code> exporters; native access via <code>handl-plugin-ffi</code>).</p><ul><li><strong>Ports</strong> (contracts): <code>lib-concurrent</code>, <code>lib-compress</code>, <code>lib-fetch</code>, <code>lib-ws</code>, <code>lib-tls</code>, <code>lib-serve</code>, <code>lib-ws-frame</code>, <code>lib-str</code>, <code>lib-math</code>, <code>lib-time</code>, <code>lib-cli</code> (two modules — <code>cli</code> port + <code>cli-c</code> libc backend), …</li><li><strong>Impls</strong>: <code>lib-&lt;port&gt;-&lt;backend&gt;</code> — <code>lib-time-c</code>, <code>lib-str-handl</code>, <code>lib-math-js</code>, <code>lib-concurrent-epoll</code>, <code>lib-fetch-c</code>, <code>lib-fetch-js</code>, <code>lib-ws-c</code>, <code>lib-tls-libssl</code>, <code>lib-compress-{gzip,zlib}-c</code>, <code>lib-cli</code> (<code>cli-c</code>), …</li><li><strong>Runtime internals</strong>: <code>lib-loader</code>, <code>lib-desugar</code>, <code>lib-tag</code> (embedded by host crates via <code>*_HNL</code> consts)</li><li><strong>FFI surfaces</strong>: <code>lib-types</code> (<code>types/c/*</code> aliases), <code>lib-libc</code>, <code>lib-curl</code>, <code>lib-libz</code> (sdkgen bindings)</li><li><code>pkg.hnl</code> declares <code>{ deps, modules }</code>; dep keys map to <code>handl-lang/lib-&lt;dep&gt;</code>.</li></ul><h2 id="kit-1" tabindex="-1"><code>kit-*</code> (1) <a class="header-anchor" href="#kit-1" aria-label="Permalink to “kit-* (1)”">​</a></h2><p><code>kit-canonical</code> — kit declaration only: a curated manifest of <code>lib-*</code> packages + <code>modules/ffi</code>. <code>.hnl</code> sources live in their <code>lib-*</code> repos.</p><h2 id="retired-shells" tabindex="-1">Retired shells <a class="header-anchor" href="#retired-shells" aria-label="Permalink to “Retired shells”">​</a></h2><p><code>stdlib</code> (archived — folded into <code>host/crates</code>), <code>c</code>, <code>web</code> (code shells; docs merged into <code>project/{c,web}/</code>).</p><h2 id="tool" tabindex="-1"><code>tool-*</code> <a class="header-anchor" href="#tool" aria-label="Permalink to “tool-*”">​</a></h2><p><code>tool-archhelper</code> (at <code>~/GitHub/9aia</code>)</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to “Rules”">​</a></h2><ul><li>Bare = core layer or purpose repo (meta/docs/project/…)</li><li><code>prefix-*</code> = one component kind per repo</li><li>Sole-consumer generated bindings vendor into the consumer&#39;s <code>handl-packages/generated/</code></li><li><code>lib-{port}</code> = interface contract; <code>lib-{port}-{impl}</code> = backend</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};